import React, {useEffect} from 'react';
import NotFound from '@theme-original/NotFound';
import {LEGACY_REDIRECTS} from '@site/src/utils/legacyRedirects';

// Hosts that serve the SPA shell for every extensionless path never reach the
// static redirect pages generated by @docusaurus/plugin-client-redirects, so
// legacy URLs would land on this page. Reproduce those redirects client-side,
// keeping search and hash (legacy anchors are aliased in the target articles).
function legacyRedirect() {
  if (typeof window === 'undefined') {
    return false;
  }
  const {pathname, search, hash} = window.location;
  const normalized = pathname.replace(/\/+$/, '') || '/';
  const localePrefix = normalized === '/en' || normalized.startsWith('/en/') ? '/en' : '';
  const bare = (localePrefix ? normalized.slice(3) : normalized) || '/';
  const target = LEGACY_REDIRECTS[bare];
  if (target) {
    window.location.replace(`${localePrefix}${target}${search}${hash}`);
    return true;
  }
  return false;
}

// Run synchronously when this chunk executes (before any render) and again
// on mount as a fallback.
if (typeof window !== 'undefined') {
  legacyRedirect();
}

export default function NotFoundWrapper(props) {
  useEffect(() => {
    legacyRedirect();
  }, []);
  return <NotFound {...props} />;
}
